const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('#mobile-nav').hidden=expanded;});const sharedBuild=new URLSearchParams(location.search).get('build');if(sharedBuild&&(location.pathname==='/'||location.pathname.endsWith('/index.html')))location.replace('/configure.html?build='+encodeURIComponent(sharedBuild)+location.hash);